from __future__ import annotations

import json
import os
import re
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from . import common

METADATA_NAME = "app.json"
REGISTRY_NAME = "app_registry.inc"
ENTRY_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
REGISTRY_MARKER = (
    "/* Generated by console/appmgr/discovery.py; do not edit. */\n"
)
CONVENTION_SUFFIX = "_create"


class DiscoveryError(RuntimeError):
    def __init__(
        self,
        code: str,
        message: str,
        *,
        path: Path | None = None,
    ) -> None:
        super().__init__(message)
        self.code = code
        self.path = path


@dataclass(frozen=True)
class AppEntry:
    name: str
    entry: str
    default: bool
    directory: Path


@dataclass(frozen=True)
class DiscoveryIssue:
    path: Path
    message: str


def app_directory(apps_dir: str | Path, name: str) -> Path:
    return Path(apps_dir) / name


def metadata_path(apps_dir: str | Path, name: str) -> Path:

    return app_directory(apps_dir, name) / METADATA_NAME


def root_metadata_path(apps_dir: str | Path) -> Path:

    return Path(apps_dir) / METADATA_NAME


def registry_path(apps_dir: str | Path) -> Path:
    return Path(apps_dir) / REGISTRY_NAME


def convention_symbol(name: str) -> str:
    return f"{name}{CONVENTION_SUFFIX}"


def matches_entry_convention(directory: str | Path, name: str) -> bool:

    directory = Path(directory)
    if not directory.is_dir() or directory.is_symlink():
        return False
    pattern = re.compile(
        rf"\bvoid\s+{re.escape(convention_symbol(name))}\s*\(\s*void\s*\)"
    )
    for suffix in ("*.h", "*.c"):
        for path in sorted(directory.glob(suffix)):
            if path.is_symlink() or not path.is_file():
                continue
            try:
                text = path.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            if pattern.search(text):
                return True
    return False


def scan_apps(
    apps_dir: str | Path,
) -> tuple[list[AppEntry], list[DiscoveryIssue]]:

    root = Path(apps_dir)
    entries: list[AppEntry] = []
    issues: list[DiscoveryIssue] = []
    if not root.is_dir():
        issues.append(DiscoveryIssue(root, "app directory does not exist"))
        return entries, issues

    default_name: str | None = None
    try:
        default_name = _read_root_metadata(root)
    except DiscoveryError as exc:
        issues.append(DiscoveryIssue(root_metadata_path(root), str(exc)))

    for path in sorted(root.iterdir()):
        if not path.is_dir() or path.is_symlink():
            continue
        try:
            entry = _read_entry(path, default_name)
        except DiscoveryError as exc:
            issues.append(DiscoveryIssue(path, str(exc)))
            continue
        if entry is not None:
            entries.append(entry)

    if default_name is not None and not any(
        entry.name == default_name for entry in entries
    ):
        issues.append(
            DiscoveryIssue(
                root_metadata_path(root),
                f'default app "{default_name}" is not a discovered app',
            )
        )
    return entries, issues


def discover_apps(apps_dir: str | Path) -> list[AppEntry]:

    entries, issues = scan_apps(apps_dir)
    if issues:
        first = issues[0]
        raise DiscoveryError(
            "app_metadata_invalid",
            f"{first.path}: {first.message}",
            path=first.path,
        )
    if not entries:
        raise DiscoveryError(
            "app_missing",
            f"no apps found in {apps_dir}",
            path=Path(apps_dir),
        )
    return _ordered(entries)


def default_app_name(apps_dir: str | Path) -> str | None:

    entries, _issues = scan_apps(apps_dir)
    defaults = [entry for entry in entries if entry.default]
    return defaults[0].name if len(defaults) == 1 else None


def find_app(apps_dir: str | Path, name: str) -> AppEntry | None:
    for entry in discover_apps(apps_dir):
        if entry.name == name:
            return entry
    return None


def write_registry(apps_dir: str | Path) -> Path:

    root = Path(apps_dir)
    entries = discover_apps(root)
    data = render_registry(entries).encode("utf-8")
    target = registry_path(root)
    if target.is_file() and target.read_bytes() == data:
        return target
    fd, temp_name = tempfile.mkstemp(
        prefix=f".{REGISTRY_NAME}.", suffix=".tmp", dir=str(root)
    )
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temp_name, target)
    except BaseException:
        try:
            os.unlink(temp_name)
        except FileNotFoundError:
            pass
        raise
    return target


def render_registry(entries: list[AppEntry]) -> str:
    ordered = _ordered(entries)
    lines = [
        REGISTRY_MARKER.rstrip("\n"),
        "#ifndef LVGL_VERIFY_LOOP_APP_REGISTRY_INC",
        "#define LVGL_VERIFY_LOOP_APP_REGISTRY_INC",
        "",
    ]
    for entry in ordered:
        lines.append(f"void {entry.entry}(void);")
    lines.extend(["", "static const app_entry_t apps[] = {"])
    for entry in ordered:
        lines.append(f'    {{"{entry.name}", {entry.entry}}},')
    lines.extend(["};", "", "#endif", ""])
    return "\n".join(lines)


def _read_entry(directory: Path, default_name: str | None) -> AppEntry | None:

    name = directory.name
    metadata = directory / METADATA_NAME
    has_metadata = metadata.is_file() and not metadata.is_symlink()
    if not has_metadata and not matches_entry_convention(directory, name):
        return None
    if not common.NAME_RE.fullmatch(name):
        raise DiscoveryError(
            "app_metadata_invalid",
            f"app directory name {name!r} must match ^[a-z][a-z0-9_]{{0,31}}$",
        )
    entry = (
        _read_metadata(metadata) if has_metadata else convention_symbol(name)
    )
    return AppEntry(
        name=name,
        entry=entry,
        default=name == default_name,
        directory=directory,
    )


def _read_metadata(path: Path) -> str:
    try:
        payload: Any = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, ValueError) as exc:
        raise DiscoveryError(
            "app_metadata_invalid", f"cannot read {METADATA_NAME}: {exc}"
        ) from exc
    if not isinstance(payload, dict):
        raise DiscoveryError(
            "app_metadata_invalid", f"{METADATA_NAME} must be an object"
        )
    entry = payload.get("entry")
    if not isinstance(entry, str) or not ENTRY_RE.fullmatch(entry):
        raise DiscoveryError(
            "app_metadata_invalid",
            f"{METADATA_NAME} entry must be a C identifier",
        )
    return entry


def _read_root_metadata(apps_dir: Path) -> str | None:
    path = root_metadata_path(apps_dir)
    if not path.is_file() or path.is_symlink():
        return None
    try:
        payload: Any = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, ValueError) as exc:
        raise DiscoveryError(
            "app_metadata_invalid",
            f"cannot read root {METADATA_NAME}: {exc}",
        ) from exc
    if not isinstance(payload, dict):
        raise DiscoveryError(
            "app_metadata_invalid", f"root {METADATA_NAME} must be an object"
        )
    default = payload.get("default")
    if default is None:
        return None
    if not isinstance(default, str) or not common.NAME_RE.fullmatch(default):
        raise DiscoveryError(
            "app_metadata_invalid",
            f"root {METADATA_NAME} default must be an app name",
        )
    return default


def _ordered(entries: list[AppEntry]) -> list[AppEntry]:
    defaults = [entry for entry in entries if entry.default]
    default = defaults[0] if defaults else None
    if default is None and entries:
        default = sorted(entries, key=lambda item: item.name)[0]
    rest = sorted(
        (entry for entry in entries if entry is not default),
        key=lambda item: item.name,
    )
    return ([default] if default is not None else []) + rest
